 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>

#include <netutils/cJSON.h>

#include "xiaozhi_ota.h"
#include "xiaozhi_ws.h"
#include "xiaozhi_audio.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define XIAOZHI_MAC_DEFAULT "6b:48:a8:95:7d:e1"
#define XZ_OPUS_MAX        400
#define XZ_DIALOG_SECONDS  4      /* capture duration per turn */

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct xiaozhi_app_s
{
  struct xiaozhi_ws_s    ws;
  struct xiaozhi_audio_s audio;
  char session_id[16];
  bool ws_connected;
  bool got_stt;
  bool tts_playing;
  int  tts_sentences;
};

/* Context shared with the uplink worker thread. */
struct uplink_ctx_s
{
  struct xiaozhi_app_s *app;
  int seconds;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct xiaozhi_app_s g_app;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* Send a JSON text frame built with cJSON. */
static int send_json(struct xiaozhi_app_s *app, cJSON *root)
{
  char *json = cJSON_PrintUnformatted(root);
  if (json == NULL)
    {
      return -ENOMEM;
    }

  int ret = xiaozhi_ws_send_text(&app->ws, json, strlen(json));
  free(json);
  return ret;
}

