  printf("[xiaozhi] step 4: listen start + capture\n");
  {
    cJSON *hello = cJSON_CreateObject();
    cJSON_AddStringToObject(hello, "session_id", g_app.session_id);
    cJSON_AddStringToObject(hello, "type", "listen");
    cJSON_AddStringToObject(hello, "state", "start");
    cJSON_AddStringToObject(hello, "mode", "manual");
    send_json(&g_app, hello);
    cJSON_Delete(hello);
    printf("[xiaozhi] >>> listen start\n");
  }

  /* Start capture and run uplink worker for N seconds. */
  ret = xiaozhi_audio_start_capture(&g_app.audio);
  if (ret != 0)
    {
      printf("[xiaozhi] capture start failed: %d\n", ret);
      goto out;
    }

  /* Drain any incoming binary/text while capturing by spawning uplink in
   * a thread and looping recv here too. Simplest: run uplink synchronously
   * (block on capture), the server tolerates a gap before listen stop.
   */
  uc.app = &g_app;
  uc.seconds = XZ_DIALOG_SECONDS;
  uplink_worker(&uc);

  xiaozhi_audio_stop_capture(&g_app.audio);

  /* listen stop. */
  {
    cJSON *stop = cJSON_CreateObject();
    cJSON_AddStringToObject(stop, "session_id", g_app.session_id);
    cJSON_AddStringToObject(stop, "type", "listen");
    cJSON_AddStringToObject(stop, "state", "stop");
    send_json(&g_app, stop);
    cJSON_Delete(stop);
    printf("[xiaozhi] >>> listen stop\n");
  }

  /* Step 5: receive stt + tts + playback (up to 20s). */
  printf("[xiaozhi] step 5: wait stt/tts (20s)\n");
  recv_loop(&g_app, 20000);

