int main(int argc, FAR char *argv[])
{
  struct xiaozhi_ota_config_s ota;
  const char *mac = XIAOZHI_MAC_DEFAULT;
  char client_id[40];
  int ret;
  struct uplink_ctx_s uc;

  memset(&g_app, 0, sizeof(g_app));

  printf("[xiaozhi] === Phase 2: full dialog ===\n");

  snprintf(client_id, sizeof(client_id),
           "00000000-0000-0000-0000-%08x", 0xa1b2c3d7);

  /* Init audio subsystem. */
  ret = xiaozhi_audio_init(&g_app.audio);
  if (ret != 0)
    {
      printf("[xiaozhi] audio init failed: %d\n", ret);
      return 1;
    }

  /* Step 1: OTA. */
  printf("[xiaozhi] step 1: OTA\n");
  ret = xiaozhi_ota_fetch(mac, &ota);
  if (ret != 0)
    {
      printf("[xiaozhi] OTA failed: %d\n", ret);
      return 1;
    }

  /* Step 2: wss connect + hello. */
  printf("[xiaozhi] step 2: wss connect\n");
  ret = xiaozhi_ws_connect(&g_app.ws, ota.ws_url, ota.ws_token, mac,
                           client_id);
  if (ret != 0)
    {
      printf("[xiaozhi] ws connect failed: %d\n", ret);
      return 1;
    }

  g_app.ws_connected = true;

  /* Wait for hello response to get session_id. */
  printf("[xiaozhi] step 3: wait hello\n");
  recv_loop(&g_app, 5000);   /* up to 5s for hello */
  if (g_app.session_id[0] == '\0')
    {
      printf("[xiaozhi] no session_id, abort\n");
      goto out;
    }

  /* Step 4: listen start + capture + listen stop. */
  printf("[xiaozhi] step 4: listen start + capture\n");
  {
    cJSON *hello = cJSON_CreateObject();
    cJSON_AddStringToObject(hello, "session_id", g_app.session_id);
    cJSON_AddStringToObject(hello, "type", "listen");
    cJSON_AddStringToObject(hello, "state", "start");
    cJSON_AddStringToObject(hello, "mode", "manual");
    send_json(&g_app, hello);
    cJSON_Delete(hello);
    printf("[xiaozhi] >>> listen start\n");
  }

  /* Start capture and run uplink worker for N seconds. */
  ret = xiaozhi_audio_start_capture(&g_app.audio);
  if (ret != 0)
    {
      printf("[xiaozhi] capture start failed: %d\n", ret);
      goto out;
    }

  /* Drain any incoming binary/text while capturing by spawning uplink in
   * a thread and looping recv here too. Simplest: run uplink synchronously
   * (block on capture), the server tolerates a gap before listen stop.
   */
  uc.app = &g_app;
  uc.seconds = XZ_DIALOG_SECONDS;
  uplink_worker(&uc);

  xiaozhi_audio_stop_capture(&g_app.audio);

